20	import createSeriesDataSimply from './createSeriesDataSimply';
21	import * as zrUtil from 'zrender/src/core/util';
22	import {getDimensionTypeByAxis} from '../../data/helper/dimensionHelper';
23	import {makeSeriesEncodeForAxisCoordSys} from '../../data/helper/sourceHelper';
24	import type { SeriesOption, SeriesOnCartesianOptionMixin, LayoutOrient } from '../../util/types';
25	import type GlobalModel from '../../model/Global';
26	import type SeriesModel from '../../model/Series';
27	import type CartesianAxisModel from '../../coord/cartesian/AxisModel';
28	import type SeriesData from '../../data/SeriesData';
29	import type Axis2D from '../../coord/cartesian/Axis2D';
30	import { CoordDimensionDefinition } from '../../data/helper/createDimensions';
31	
32	interface CommonOption extends SeriesOption, SeriesOnCartesianOptionMixin {
33	    layout?: LayoutOrient
34	
35	    // data?: (DataItemOption | number[])[]
36	}
37	
38	type WhiskerBoxCommonData = (DataItemOption | number[])[];
39	
40	interface DataItemOption {
41	    value?: number[]
42	}
43	
44	interface WhiskerBoxCommonMixin<Opts extends CommonOption> extends SeriesModel<Opts>{}
45	class WhiskerBoxCommonMixin<Opts extends CommonOption> {
46	
47	    /**
48	     * @private
49	     * @type {string}
50	     */
51	    _baseAxisDim: string;
52	
53	    defaultValueDimensions: CoordDimensionDefinition['dimsDef'];
54	
55	    /**
56	     * @override
57	     */
58	    getInitialData(option: Opts, ecModel: GlobalModel): SeriesData {
59	        // When both types of xAxis and yAxis are 'value', layout is
60	        // needed to be specified by user. Otherwise, layout can be
61	        // judged by which axis is category.
62	
63	        let ordinalMeta;
64	
65	        const xAxisModel = ecModel.getComponent('xAxis', this.get('xAxisIndex')) as CartesianAxisModel;
66	        const yAxisModel = ecModel.getComponent('yAxis', this.get('yAxisIndex')) as CartesianAxisModel;
67	        const xAxisType = xAxisModel.get('type');
68	        const yAxisType = yAxisModel.get('type');
69	        let addOrdinal;
70	
71	        // FIXME
72	        // Consider time axis.
73	
74	        if (xAxisType === 'category') {
75	            option.layout = 'horizontal';
76	            ordinalMeta = xAxisModel.getOrdinalMeta();
77	            addOrdinal = true;
78	        }
79	        else if (yAxisType === 'category') {
80	            option.layout = 'vertical';
81	            ordinalMeta = yAxisModel.getOrdinalMeta();
82	            addOrdinal = true;
83	        }
84	        else {
85	            option.layout = option.layout || 'horizontal';
86	        }
87	
88	        const coordDims = ['x', 'y'];
89	        const baseAxisDimIndex = option.layout === 'horizontal' ? 0 : 1;
90	        const baseAxisDim = this._baseAxisDim = coordDims[baseAxisDimIndex];
91	        const otherAxisDim = coordDims[1 - baseAxisDimIndex];
92	        const axisModels = [xAxisModel, yAxisModel];
93	        const baseAxisType = axisModels[baseAxisDimIndex].get('type');
94	        const otherAxisType = axisModels[1 - baseAxisDimIndex].get('type');
95	        const data = option.data as WhiskerBoxCommonData;
96	
97	        // Clone a new data for next setOption({}) usage.
98	        // Avoid modifying current data will affect further update.
99	        if (data && addOrdinal) {
100	            const newOptionData: WhiskerBoxCommonData = [];
101	            zrUtil.each(data, function (item, index) {
102	                let newItem;
103	                if (zrUtil.isArray(item)) {
104	                    newItem = item.slice();
105	                    // Modify current using data.
106	                    item.unshift(index);
107	                }
108	                else if (zrUtil.isArray(item.value)) {
109	                    newItem = zrUtil.extend({}, item);
110	                    newItem.value = newItem.value.slice();
111	                    // Modify current using data.
112	                    item.value.unshift(index);
113	                }
114	                else {
115	                    newItem = item;
116	                }
117	                newOptionData.push(newItem);
118	            });
119	            option.data = newOptionData;
120	        }
121	
122	        const defaultValueDimensions = this.defaultValueDimensions;
123	        const coordDimensions: CoordDimensionDefinition[] = [{
124	            name: baseAxisDim,
125	            type: getDimensionTypeByAxis(baseAxisType),
126	            ordinalMeta: ordinalMeta,
127	            otherDims: {
128	                tooltip: false,
129	                itemName: 0
130	            },
131	            dimsDef: ['base']
132	        }, {
133	            name: otherAxisDim,
134	            type: getDimensionTypeByAxis(otherAxisType),
135	            dimsDef: defaultValueDimensions.slice()
136	        }];
137	
138	        return createSeriesDataSimply(
139	            this,
140	            {
141	                coordDimensions: coordDimensions,
142	                dimensionsCount: defaultValueDimensions.length + 1,
143	                encodeDefaulter: zrUtil.curry(
144	                    makeSeriesEncodeForAxisCoordSys, coordDimensions, this as any
145	                )
146	            }
147	        );
148	    }
149	
150	    /**
151	     * If horizontal, base axis is x, otherwise y.
152	     * @override
153	     */
154	    getBaseAxis(): Axis2D {
155	        const dim = this._baseAxisDim;
156	        return (this.ecModel.getComponent(
157	            dim + 'Axis', this.get(dim + 'AxisIndex' as 'xAxisIndex' | 'yAxisIndex')
158	        ) as CartesianAxisModel).axis;
159	    }
160	
161	};
162	
163	
164	export {WhiskerBoxCommonMixin};

