25	/**
26	 * [Usage]:
27	 * (1)
28	 * createListSimply(seriesModel, ['value']);
29	 * (2)
30	 * createListSimply(seriesModel, {
31	 *     coordDimensions: ['value'],
32	 *     dimensionsCount: 5
33	 * });
34	 */
35	export default function createSeriesDataSimply(
36	    seriesModel: SeriesModel,
37	    opt: PrepareSeriesDataSchemaParams | PrepareSeriesDataSchemaParams['coordDimensions'],
38	    nameList?: string[]
39	): SeriesData {
40	    opt = isArray(opt) && {
41	        coordDimensions: opt
42	    } || extend({
43	        encodeDefine: seriesModel.getEncode()
44	    }, opt);
45	
46	    const source = seriesModel.getSource();
47	
48	    const { dimensions } = prepareSeriesDataSchema(source, opt as PrepareSeriesDataSchemaParams);
49	
50	    const list = new SeriesData(dimensions, seriesModel);
51	    list.initData(source, nameList);
52	
53	    return list;
54	}
