88	/**
89	 * This method builds the relationship between:
90	 * + "what the coord sys or series requires (see `coordDimensions`)",
91	 * + "what the user defines (in `encode` and `dimensions`, see `opt.dimensionsDefine` and `opt.encodeDefine`)"
92	 * + "what the data source provids (see `source`)".
93	 *
94	 * Some guess strategy will be adapted if user does not define something.
95	 * If no 'value' dimension specified, the first no-named dimension will be
96	 * named as 'value'.
97	 *
98	 * @return The results are always sorted by `storeDimIndex` asc.
99	 */
100	export default function prepareSeriesDataSchema(
101	    // TODO: TYPE completeDimensions type
102	    source: Source | OptionSourceData,
103	    opt?: PrepareSeriesDataSchemaParams
104	): SeriesDataSchema {
105	    if (!isSourceInstance(source)) {
106	        source = createSourceFromSeriesDataOption(source as OptionSourceData);
107	    }
108	
109	    opt = opt || {};
110	
111	    const sysDims = opt.coordDimensions || [];
112	    const dimsDef = opt.dimensionsDefine || source.dimensionsDefine || [];
113	    const coordDimNameMap = createHashMap<true, DimensionName>();
114	    const resultList: SeriesDimensionDefine[] = [];
115	    const dimCount = getDimCount(source, sysDims, dimsDef, opt.dimensionsCount);
116	
117	    // Try to ignore unused dimensions if sharing a high dimension datastore
118	    // 30 is an experience value.
119	    const omitUnusedDimensions = opt.canOmitUnusedDimensions && shouldOmitUnusedDimensions(dimCount);
120	
121	    const isUsingSourceDimensionsDef = dimsDef === source.dimensionsDefine;
122	    const dataDimNameMap = isUsingSourceDimensionsDef
123	        ? ensureSourceDimNameMap(source) : createDimNameMap(dimsDef);
124	
125	    let encodeDef = opt.encodeDefine;
126	    if (!encodeDef && opt.encodeDefaulter) {
127	        encodeDef = opt.encodeDefaulter(source, dimCount);
128	    }
129	    const encodeDefMap = createHashMap<DimensionIndex[] | false, DimensionName>(encodeDef as any);
130	
131	    const indicesMap = new CtorInt32Array(dimCount);
132	    for (let i = 0; i < indicesMap.length; i++) {
133	        indicesMap[i] = -1;
134	    }
135	
136	    function getResultItem(dimIdx: number) {
137	        const idx = indicesMap[dimIdx];
138	        if (idx < 0) {
139	            const dimDefItemRaw = dimsDef[dimIdx];
140	            const dimDefItem = isObject(dimDefItemRaw) ? dimDefItemRaw : { name: dimDefItemRaw };
141	            const resultItem = new SeriesDimensionDefine();
142	            const userDimName = dimDefItem.name;
143	            if (userDimName != null && dataDimNameMap.get(userDimName) != null) {
144	                // Only if `series.dimensions` is defined in option
145	                // displayName, will be set, and dimension will be displayed vertically in
146	                // tooltip by default.
147	                resultItem.name = resultItem.displayName = userDimName;
148	            }
149	            dimDefItem.type != null && (resultItem.type = dimDefItem.type);
150	            dimDefItem.displayName != null && (resultItem.displayName = dimDefItem.displayName);
151	            const newIdx = resultList.length;
152	            indicesMap[dimIdx] = newIdx;
153	            resultItem.storeDimIndex = dimIdx;
154	            resultList.push(resultItem);
155	            return resultItem;
156	        }
157	        return resultList[idx];
158	    }
159	
160	    if (!omitUnusedDimensions) {
161	        for (let i = 0; i < dimCount; i++) {
162	            getResultItem(i);
163	        }
164	    }
165	
166	    // Set `coordDim` and `coordDimIndex` by `encodeDefMap` and normalize `encodeDefMap`.
167	    encodeDefMap.each(function (dataDimsRaw, coordDim) {
168	        const dataDims = normalizeToArray(dataDimsRaw as []).slice();
169	
170	        // Note: It is allowed that `dataDims.length` is `0`, e.g., options is
171	        // `{encode: {x: -1, y: 1}}`. Should not filter anything in
172	        // this case.
173	        if (dataDims.length === 1 && !isString(dataDims[0]) && dataDims[0] < 0) {
174	            encodeDefMap.set(coordDim, false);
175	            return;
176	        }
177	
178	        const validDataDims = encodeDefMap.set(coordDim, []) as DimensionIndex[];
179	        each(dataDims, function (resultDimIdxOrName, idx) {
180	            // The input resultDimIdx can be dim name or index.
181	            const resultDimIdx = isString(resultDimIdxOrName)
182	                ? dataDimNameMap.get(resultDimIdxOrName)
183	                : resultDimIdxOrName;
184	            if (resultDimIdx != null && resultDimIdx < dimCount) {
185	                validDataDims[idx] = resultDimIdx;
186	                applyDim(getResultItem(resultDimIdx), coordDim, idx);
187	            }
188	        });
189	    });
190	
191	    // Apply templates and default order from `sysDims`.
192	    let availDimIdx = 0;
193	    each(sysDims, function (sysDimItemRaw) {
194	        let coordDim: DimensionName;
195	        let sysDimItemDimsDef: CoordDimensionDefinition['dimsDef'];
196	        let sysDimItemOtherDims: CoordDimensionDefinition['otherDims'];
197	        let sysDimItem: CoordDimensionDefinition;
198	        if (isString(sysDimItemRaw)) {
199	            coordDim = sysDimItemRaw;
200	            sysDimItem = {} as CoordDimensionDefinition;
201	        }
202	        else {
203	            sysDimItem = sysDimItemRaw;
204	            coordDim = sysDimItem.name;
205	            const ordinalMeta = sysDimItem.ordinalMeta;
206	            sysDimItem.ordinalMeta = null;
207	            sysDimItem = extend({}, sysDimItem);
208	            sysDimItem.ordinalMeta = ordinalMeta;
209	            // `coordDimIndex` should not be set directly.
210	            sysDimItemDimsDef = sysDimItem.dimsDef;
211	            sysDimItemOtherDims = sysDimItem.otherDims;
212	            sysDimItem.name = sysDimItem.coordDim = sysDimItem.coordDimIndex =
213	                sysDimItem.dimsDef = sysDimItem.otherDims = null;
214	        }
215	
216	        let dataDims = encodeDefMap.get(coordDim);
217	
218	        // negative resultDimIdx means no need to mapping.
219	        if (dataDims === false) {
220	            return;
221	        }
222	
223	        dataDims = normalizeToArray(dataDims);
224	
225	        // dimensions provides default dim sequences.
226	        if (!dataDims.length) {
227	            for (let i = 0; i < (sysDimItemDimsDef && sysDimItemDimsDef.length || 1); i++) {
228	                while (availDimIdx < dimCount && getResultItem(availDimIdx).coordDim != null) {
229	                    availDimIdx++;
230	                }
231	                availDimIdx < dimCount && dataDims.push(availDimIdx++);
232	            }
233	        }
234	
235	        // Apply templates.
236	        each(dataDims, function (resultDimIdx, coordDimIndex) {
237	            const resultItem = getResultItem(resultDimIdx);
238	            // Coordinate system has a higher priority on dim type than source.
239	            if (isUsingSourceDimensionsDef && sysDimItem.type != null) {
240	                resultItem.type = sysDimItem.type;
241	            }
242	            applyDim(defaults(resultItem, sysDimItem), coordDim, coordDimIndex);
243	            if (resultItem.name == null && sysDimItemDimsDef) {
244	                let sysDimItemDimsDefItem = sysDimItemDimsDef[coordDimIndex];
245	                !isObject(sysDimItemDimsDefItem) && (sysDimItemDimsDefItem = {
246	                    name: sysDimItemDimsDefItem
247	                });
248	                resultItem.name = resultItem.displayName = sysDimItemDimsDefItem.name;
249	                resultItem.defaultTooltip = sysDimItemDimsDefItem.defaultTooltip;
250	            }
251	            // FIXME refactor, currently only used in case: {otherDims: {tooltip: false}}
252	            sysDimItemOtherDims && defaults(resultItem.otherDims, sysDimItemOtherDims);
253	        });
254	    });
255	
256	    function applyDim(resultItem: SeriesDimensionDefine, coordDim: DimensionName, coordDimIndex: DimensionIndex) {
257	        if (VISUAL_DIMENSIONS.get(coordDim as keyof DataVisualDimensions) != null) {
258	            resultItem.otherDims[coordDim as keyof DataVisualDimensions] = coordDimIndex;
259	        }
260	        else {
261	            resultItem.coordDim = coordDim;
262	            resultItem.coordDimIndex = coordDimIndex;
263	            coordDimNameMap.set(coordDim, true);
264	        }
265	    }
266	
267	    // Make sure the first extra dim is 'value'.
268	    const generateCoord = opt.generateCoord;
269	    let generateCoordCount = opt.generateCoordCount;
270	    const fromZero = generateCoordCount != null;
271	    generateCoordCount = generateCoord ? (generateCoordCount || 1) : 0;
272	    const extra = generateCoord || 'value';
273	
274	    function ifNoNameFillWithCoordName(resultItem: SeriesDimensionDefine): void {
275	        if (resultItem.name == null) {
276	            // Duplication will be removed in the next step.
277	            resultItem.name = resultItem.coordDim;
278	        }
279	    }
280	
281	    // Set dim `name` and other `coordDim` and other props.
282	    if (!omitUnusedDimensions) {
283	        for (let resultDimIdx = 0; resultDimIdx < dimCount; resultDimIdx++) {
284	            const resultItem = getResultItem(resultDimIdx);
285	            const coordDim = resultItem.coordDim;
286	
287	            if (coordDim == null) {
288	                // TODO no need to generate coordDim for isExtraCoord?
289	                resultItem.coordDim = genCoordDimName(
290	                    extra, coordDimNameMap, fromZero
291	                );
292	
293	                resultItem.coordDimIndex = 0;
294	                // Series specified generateCoord is using out.
295	                if (!generateCoord || generateCoordCount <= 0) {
296	                    resultItem.isExtraCoord = true;
297	                }
298	                generateCoordCount--;
299	            }
300	
301	            ifNoNameFillWithCoordName(resultItem);
302	
303	            if (resultItem.type == null
304	                && (
305	                    guessOrdinal(source, resultDimIdx) === BE_ORDINAL.Must
306	                    // Consider the case:
307	                    // {
308	                    //    dataset: {source: [
309	                    //        ['2001', 123],
310	                    //        ['2002', 456],
311	                    //        ...
312	                    //        ['The others', 987],
313	                    //    ]},
314	                    //    series: {type: 'pie'}
315	                    // }
316	                    // The first column should better be treated as a "ordinal" although it
317	                    // might not be detected as an "ordinal" by `guessOrdinal`.
318	                    || (resultItem.isExtraCoord
319	                        && (resultItem.otherDims.itemName != null
320	                            || resultItem.otherDims.seriesName != null
321	                        )
322	                    )
323	                )
324	            ) {
325	                resultItem.type = 'ordinal';
326	            }
327	        }
328	    }
329	    else {
330	        each(resultList, resultItem => {
331	            // PENDING: guessOrdinal or let user specify type: 'ordinal' manually?
332	            ifNoNameFillWithCoordName(resultItem);
333	        });
334	        // Sort dimensions: there are some rule that use the last dim as label,
335	        // and for some latter travel process easier.
336	        resultList.sort((item0, item1) => item0.storeDimIndex - item1.storeDimIndex);
337	    }
338	
339	    removeDuplication(resultList);
340	
341	    return new SeriesDataSchema({
342	        source,
343	        dimensions: resultList,
344	        fullDimensionCount: dimCount,
345	        dimensionOmitted: omitUnusedDimensions
346	    });
347	}
348	
349	function removeDuplication(result: SeriesDimensionDefine[]) {
350	    const duplicationMap = createHashMap<number>();
351	    for (let i = 0; i < result.length; i++) {
352	        const dim = result[i];
353	        const dimOriginalName = dim.name;
354	        let count = duplicationMap.get(dimOriginalName) || 0;
355	        if (count > 0) {
356	            // Starts from 0.
357	            dim.name = dimOriginalName + (count - 1);
358	        }
359	        count++;
360	        duplicationMap.set(dimOriginalName, count);
361	    }
362	}
363	
364	// ??? TODO
365	// Originally detect dimCount by data[0]. Should we
366	// optimize it to only by sysDims and dimensions and encode.
367	// So only necessary dims will be initialized.
368	// But
369	// (1) custom series should be considered. where other dims
370	// may be visited.
371	// (2) sometimes user need to calculate bubble size or use visualMap
372	// on other dimensions besides coordSys needed.
373	// So, dims that is not used by system, should be shared in data store?
374	function getDimCount(
375	    source: Source,
376	    sysDims: CoordDimensionDefinitionLoose[],
377	    dimsDef: DimensionDefinitionLoose[],
378	    optDimCount?: number
379	): number {
380	    // Note that the result dimCount should not small than columns count
381	    // of data, otherwise `dataDimNameMap` checking will be incorrect.
382	    let dimCount = Math.max(
383	        source.dimensionsDetectedCount || 1,
384	        sysDims.length,
385	        dimsDef.length,
386	        optDimCount || 0
387	    );
388	    each(sysDims, function (sysDimItem) {
389	        let sysDimItemDimsDef;
390	        if (isObject(sysDimItem) && (sysDimItemDimsDef = sysDimItem.dimsDef)) {
391	            dimCount = Math.max(dimCount, sysDimItemDimsDef.length);
392	        }
393	    });
394	    return dimCount;
395	}
396	
397	function genCoordDimName(
398	    name: DimensionName,
399	    map: HashMap<unknown, DimensionName>,
400	    fromZero: boolean
401	) {
402	    if (fromZero || map.hasKey(name)) {
403	        let i = 0;
404	        while (map.hasKey(name + i)) {
405	            i++;
406	        }
407	        name += i;
408	    }
409	    map.set(name, true);
410	    return name;
411	}
