        this._encode = encode;
        this._schema = dimRequest;
    }

    get(): {
        fullDimensions: DimensionName[];
        encode: DimensionUserOuputEncode;
    } {
        return {
            // Do not generate full dimension name until fist used.
            fullDimensions: this._getFullDimensionNames(),
            encode: this._encode
