function dump(chart: EChartsType, label: string, seriesIdx?: number) {
    const series = getECModel(chart).getSeriesByIndex(seriesIdx || 0);
    const data = series.getData();
    const out: any = {
        dims: data.dimensions.slice(),
        info: data.dimensions.map(d => {
            const i = data.getDimensionInfo(d);
            return d + ':' + i.coordDim + '/' + i.coordDimIndex + '/' + i.storeDimIndex + '/' + i.type;
        }),
        x: data.mapDimension('x'),
        y: data.mapDimensionsAll('y'),
        xAll: data.mapDimensionsAll('x'),
        rows: [] as any[]
    };
    for (let i = 0; i < data.count(); i++) {
        out.rows.push([data.getName(i), data.getValues(i), !!data.getItemLayout(i)]);
    }
    console.log(label, JSON.stringify(out));
}

