import { EChartsType } from '@/src/echarts';
import { createChart, getECModel } from '../../../core/utHelper';
import type CartesianAxisModel from '@/src/coord/cartesian/AxisModel';

type BoxplotResult = {
    categories: unknown[]
    values: number[][]
    elCount: number
};

function readBoxplot(chart: EChartsType, categoryAxisDim: 'x' | 'y'): BoxplotResult {
    const ecModel = getECModel(chart);
    const seriesModel = ecModel.getSeriesByIndex(0);
    const data = seriesModel.getData();
    const axisModel = ecModel.getComponent(
        categoryAxisDim + 'Axis', 0
    ) as CartesianAxisModel;

    const cDim = data.mapDimension(categoryAxisDim);
    const vDims = data.mapDimensionsAll(categoryAxisDim === 'x' ? 'y' : 'x');

    const categories: unknown[] = [];
    const values: number[][] = [];
    let elCount = 0;

    for (let i = 0; i < data.count(); i++) {
        // The base dim of a boxplot on a category axis stores the ordinal index.
        categories.push(
            axisModel.getOrdinalMeta().categories[data.get(cDim, i) as number]
        );
        values.push(vDims.map(dim => data.get(dim, i) as number));
    }
    data.eachItemGraphicEl(function () {
        elCount++;
    });

    return { categories, values, elCount };
}

