                    ['min', 'Q1', 'median', 'Q3', 'max', 'name'],
                    [10, 20, 30, 40, 50, 'one'],
                    [33, 38, 39, 40, 55, 'two'],
                    [40, 45, 50, 52, 66, 'three']
                ]
            },
            xAxis: { type: 'category' },
            yAxis: { type: 'value' },
            series: [{
                type: 'boxplot',
                encode: { x: [5], y: [0, 1, 2, 3, 4] }
            }]
        });

        const result = readBoxplot(chart, 'x');
        expect(result.categories).toEqual(['one', 'two', 'three']);
        expect(result.values).toEqual([
            [10, 20, 30, 40, 50],
            [33, 38, 39, 40, 55],
            [40, 45, 50, 52, 66]
        ]);
        expect(result.elCount).toEqual(3);
    });

    it('should use the encoded dimensions of series data on a category x axis', function () {
        chart.setOption({
            animation: false,
            xAxis: { type: 'category' },
            yAxis: { type: 'value' },
            series: [{
                type: 'boxplot',
                encode: { x: [5], y: [0, 1, 2, 3, 4] },
                data: [
                    [10, 20, 30, 40, 50, 'one'],
                    [33, 38, 39, 40, 55, 'two'],
                    [40, 45, 50, 52, 66, 'three']
                ]
            }]
        });

        const result = readBoxplot(chart, 'x');
        expect(result.categories).toEqual(['one', 'two', 'three']);
        expect(result.values).toEqual([
            [10, 20, 30, 40, 50],
            [33, 38, 39, 40, 55],
            [40, 45, 50, 52, 66]
        ]);
        expect(result.elCount).toEqual(3);
    });

    it('should use the encoded dimensions on a category y axis', function () {
        chart.setOption({
            animation: false,
            xAxis: { type: 'value' },
            yAxis: { type: 'category' },
            series: [{
                type: 'boxplot',
                encode: { y: [5], x: [0, 1, 2, 3, 4] },
                data: [
                    [10, 20, 30, 40, 50, 'one'],
                    [33, 38, 39, 40, 55, 'two'],
                    [40, 45, 50, 52, 66, 'three']
                ]
            }]
        });

        const result = readBoxplot(chart, 'y');
        expect(result.categories).toEqual(['one', 'two', 'three']);
        expect(result.values).toEqual([
            [10, 20, 30, 40, 50],
            [33, 38, 39, 40, 55],
            [40, 45, 50, 52, 66]
        ]);
        expect(result.elCount).toEqual(3);
    });

    it('should keep using the data index as category when no encode is specified', function () {
        chart.setOption({
            animation: false,
            xAxis: { type: 'category' },
            yAxis: { type: 'value' },
            series: [{
                type: 'boxplot',
                data: [
                    [10, 20, 30, 40, 50],
                    [33, 38, 39, 40, 55],
                    [40, 45, 50, 52, 66]
                ]
            }]
        });

        const result = readBoxplot(chart, 'x');
        expect(result.categories).toEqual([0, 1, 2]);
        expect(result.values).toEqual([
            [10, 20, 30, 40, 50],
            [33, 38, 39, 40, 55],
            [40, 45, 50, 52, 66]
        ]);
        expect(result.elCount).toEqual(3);
    });
});

